namespace Contoso.Pricing.Tests;

[TestClass]
public sealed class PriceCalculatorTests
{
    private readonly PriceCalculator _calculator = new();

    // ───────────────────────────────────────────────
    // CalculateTotal — DataRow parameterized tests
    // ───────────────────────────────────────────────

    [TestMethod]
    [DataRow(10.00, 1, 0.0, 10.00, DisplayName = "Single item, no tax")]
    [DataRow(10.00, 2, 0.0, 20.00, DisplayName = "Two items, no tax")]
    [DataRow(10.00, 1, 0.10, 11.00, DisplayName = "Single item, 10% tax")]
    [DataRow(25.50, 3, 0.08, 82.62, DisplayName = "Multiple items, 8% tax")]
    [DataRow(0.00, 5, 0.20, 0.00, DisplayName = "Zero price, any quantity")]
    [DataRow(99.99, 0, 0.15, 0.00, DisplayName = "Zero quantity returns zero")]
    public void CalculateTotal_ValidInputs_ReturnsExpectedTotal(
        double unitPrice, int quantity, double taxRate, double expected)
    {
        var result = _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate);

        Assert.AreEqual((decimal)expected, result, $"Expected {expected} for unitPrice={unitPrice}, qty={quantity}, tax={taxRate}");
    }

    [TestMethod]
    [DataRow(-1.00, 1, 0.10, DisplayName = "Negative unit price throws")]
    public void CalculateTotal_NegativeUnitPrice_Throws(double unitPrice, int quantity, double taxRate)
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate));
    }

    [TestMethod]
    [DataRow(10.00, -1, 0.10, DisplayName = "Negative quantity throws")]
    public void CalculateTotal_NegativeQuantity_Throws(double unitPrice, int quantity, double taxRate)
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate));
    }

    [TestMethod]
    [DataRow(10.00, 1, -0.01, DisplayName = "Tax rate below zero throws")]
    [DataRow(10.00, 1, 1.01, DisplayName = "Tax rate above one throws")]
    public void CalculateTotal_InvalidTaxRate_Throws(double unitPrice, int quantity, double taxRate)
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate));
    }

    // ───────────────────────────────────────────────
    // ApplyDiscount — DynamicData parameterized tests
    // ───────────────────────────────────────────────

    public static IEnumerable<object[]> DiscountTestData =>
    [
        [100.00m, 0m, 100.00m],   // No discount
        [100.00m, 10m, 90.00m],   // 10% off
        [100.00m, 50m, 50.00m],   // Half off
        [100.00m, 100m, 0.00m],   // Full discount
        [59.99m, 25m, 44.9925m],  // Fractional result
        [0.00m, 50m, 0.00m],     // Zero price
    ];

    [TestMethod]
    [DynamicData(nameof(DiscountTestData))]
    public void ApplyDiscount_ValidInputs_ReturnsExpectedPrice(
        decimal price, decimal discountPercent, decimal expected)
    {
        var result = _calculator.ApplyDiscount(price, discountPercent);

        Assert.AreEqual(expected, result);
    }

    public static IEnumerable<object[]> InvalidDiscountData =>
    [
        [100.00m, -1m],
        [100.00m, 101m],
    ];

    [TestMethod]
    [DynamicData(nameof(InvalidDiscountData))]
    public void ApplyDiscount_InvalidDiscountPercent_Throws(decimal price, decimal discountPercent)
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(price, discountPercent));
    }

    // ───────────────────────────────────────────────
    // DynamicData with method source (alternative)
    // ───────────────────────────────────────────────

    public static IEnumerable<object[]> GetCalculateTotalEdgeCases()
    {
        yield return [0.01m, 1, 0.0m, 0.01m];   // Minimum meaningful price
        yield return [9999.99m, 100, 0.25m, 1249998.75m]; // Large order with tax
    }

    [TestMethod]
    [DynamicData(nameof(GetCalculateTotalEdgeCases), DynamicDataSourceType.Method)]
    public void CalculateTotal_EdgeCases_ReturnsExpectedTotal(
        decimal unitPrice, int quantity, decimal taxRate, decimal expected)
    {
        var result = _calculator.CalculateTotal(unitPrice, quantity, taxRate);

        Assert.AreEqual(expected, result);
    }
}

